rule.definition:
if(
  or(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!filter),
    len(ri!filter)<#"_a-0000e6d2-8270-8000-9c03-011c48011c48_3895397"
  ),
  #"SYSTEM_SYSRULES_dataSubset"(data: {}, identifiers: {}),
  a!localVariables(
    local!results: #"SYSTEM_SYSRULES_queryEntity_v1"(
      entity: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3924660",
      query: #"SYSTEM_SYSRULES_query"(
        selection: #"SYSTEM_SYSRULES_querySelection"(
          columns: {
            #"SYSTEM_SYSRULES_queryColumn"(field: "fullNameDerived"),
            #"SYSTEM_SYSRULES_queryColumn"(field: "employeeId"),
            #"SYSTEM_SYSRULES_queryColumn"(field: "email")
          }
        ),
        paginginfo: #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: -1
        ),
        filter: #"SYSTEM_SYSRULES_queryFilter"(
          field: "fullNameDerived",
          operator: "includes",
          value: ri!filter
        )
      )
    ),
    #"SYSTEM_SYSRULES_dataSubset"(
      data: #"SYSTEM_SYSRULES_forEach"(
        items: index(local!results, "data", {}),
        expression: concat(
          index(fv!item, "fullNameDerived", {}),
          " (",
          index(fv!item, "email", {}),
          ")"
        )
      ),
      identifiers: index(local!results.data, "employeeId", {})
    )
  )
)
